<?php
if(!defined('ABSPATH'))exit;
function bsktv_seo_plugin_active(){return defined('WPSEO_VERSION')||defined('RANK_MATH_VERSION')||defined('SEOPRESS_VERSION')||defined('AIOSEO_VERSION')||class_exists('The_SEO_Framework\Extension_Manager');}
function bsktv_schema(){if(!is_singular('post')||bsktv_seo_plugin_active())return;$id=get_the_ID();$title=wp_strip_all_tags(get_the_title());if($title==='')return;$description=wp_strip_all_tags(get_the_excerpt());if(!$description)$description=wp_trim_words(wp_strip_all_tags(get_the_content(null,false)),45,'…');$permalink=get_permalink($id);$author_id=(int)get_post_field('post_author',$id);$d=array('@type'=>'Article','@id'=>$permalink.'#article','headline'=>$title,'url'=>$permalink,'mainEntityOfPage'=>array('@type'=>'WebPage','@id'=>$permalink),'datePublished'=>get_the_date('c',$id),'dateModified'=>get_the_modified_date('c',$id),'author'=>array('@type'=>'Person','name'=>get_the_author_meta('display_name',$author_id)));if($description)$d['description']=$description;if(has_post_thumbnail($id)){$image=wp_get_attachment_image_url(get_post_thumbnail_id($id),'full');if($image)$d['image']=$image;}$business=array('@type'=>'LocalBusiness','@id'=>$permalink.'#business','name'=>$title,'url'=>$permalink);if($description)$business['description']=$description;$address=bsktv_meta('bsktv_address',$id);$hours=bsktv_meta('bsktv_hours',$id);if($address)$business['address']=array('@type'=>'PostalAddress','streetAddress'=>$address);if($hours)$business['openingHours']=$hours;$phone=bsktv_meta('bsktv_phone',$id);if($phone)$business['telephone']=$phone;$image_url=has_post_thumbnail($id)?get_the_post_thumbnail_url($id,'full'):'';if($image_url)$business['image']=$image_url;$d['about']=array('@id'=>$permalink.'#business');$cities=wp_get_post_terms($id,'bsktv_city',array('fields'=>'ids'));$city_name='店家';$city_url=home_url('/');if($cities&&!is_wp_error($cities)){$term=get_term($cities[0],'bsktv_city');if($term&&!is_wp_error($term)){$city_name=$term->name;$term_link=get_term_link($term);if(!is_wp_error($term_link))$city_url=$term_link;}}$graph=array('@context'=>'https://schema.org','@graph'=>array($d,$business,array('@type'=>'BreadcrumbList','itemListElement'=>array(array('@type'=>'ListItem','position'=>1,'name'=>'首頁','item'=>home_url('/')),array('@type'=>'ListItem','position'=>2,'name'=>$city_name,'item'=>$city_url),array('@type'=>'ListItem','position'=>3,'name'=>$title,'item'=>$permalink)))));echo '<script type="application/ld+json">'.wp_json_encode($graph,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES).'</script>';}
add_action('wp_head','bsktv_schema',20);
function bsktv_store_title($title){if(is_singular('post')&&!bsktv_seo_plugin_active()&&!is_admin()){$name=wp_strip_all_tags(get_the_title());if($name)$title=$name.'｜BSKTV 商務KTV店家資訊';}return $title;}add_filter('pre_get_document_title','bsktv_store_title',20);
function bsktv_archive_context(){if(!is_tax(array('bsktv_city','bsktv_type','bsktv_feature')))return array();$term=get_queried_object();$name=isset($term->name)?wp_strip_all_tags($term->name):'店家';$taxonomy=isset($term->taxonomy)?$term->taxonomy:'';$labels=array('bsktv_city'=>'城市','bsktv_type'=>'商務KTV類型','bsktv_feature'=>'店家特色');$prefix=$labels[$taxonomy]??'店家';$description=term_description($term);$description=wp_strip_all_tags($description);if(!$description)$description='BSKTV 收錄的'.$prefix.'「'.$name.'」店家資訊、店家介紹與相關內容。';$url=get_term_link($term);return array('name'=>$name,'prefix'=>$prefix,'description'=>wp_trim_words($description,45,'…'),'url'=>$url);}
function bsktv_archive_title($parts){if(bsktv_seo_plugin_active()||!is_tax(array('bsktv_city','bsktv_type','bsktv_feature')))return $parts;$ctx=bsktv_archive_context();if(!$ctx)return $parts;$parts['title']=$ctx['name'].'｜'.$ctx['prefix'].'｜BSKTV';$parts['site']='BSKTV';return $parts;}add_filter('document_title_parts','bsktv_archive_title',20);
function bsktv_archive_meta(){if(bsktv_seo_plugin_active()||!is_tax(array('bsktv_city','bsktv_type','bsktv_feature')))return;$ctx=bsktv_archive_context();if(!$ctx)return;$url=!is_wp_error($ctx['url'])?$ctx['url']:home_url('/');echo '<meta name="description" content="'.esc_attr($ctx['description']).'">'."\n";echo '<link rel="canonical" href="'.esc_url($url).'">'."\n";echo '<meta property="og:type" content="website">'."\n";echo '<meta property="og:site_name" content="BSKTV">'."\n";echo '<meta property="og:title" content="'.esc_attr($ctx['name'].'｜'.$ctx['prefix'].'｜BSKTV').'">'."\n";echo '<meta property="og:description" content="'.esc_attr($ctx['description']).'">'."\n";echo '<meta property="og:url" content="'.esc_url($url).'">'."\n";}add_action('wp_head','bsktv_archive_meta',5);
function bsktv_meta_description(){if(!is_singular('post')||bsktv_seo_plugin_active())return;$text=wp_strip_all_tags(get_the_excerpt());if(!$text)$text=wp_strip_all_tags(get_the_content(null,false));$text=wp_trim_words($text,45,'…');if($text)echo '<meta name="description" content="'.esc_attr($text).'">'."\n";}add_action('wp_head','bsktv_meta_description',5);
function bsktv_canonical(){if(!is_singular('post')||bsktv_seo_plugin_active())return;$url=wp_get_canonical_url();if($url)echo '<link rel="canonical" href="'.esc_url($url).'">'."\n";}add_action('wp_head','bsktv_canonical',6);
function bsktv_og_meta(){if(!is_singular('post')||bsktv_seo_plugin_active())return;$id=get_the_ID();$title=wp_strip_all_tags(get_the_title());$description=wp_strip_all_tags(get_the_excerpt());if(!$description)$description=wp_trim_words(wp_strip_all_tags(get_the_content(null,false)),45,'…');$url=get_permalink($id);$image=has_post_thumbnail($id)?get_the_post_thumbnail_url($id,'full'):'';$site=wp_strip_all_tags(get_bloginfo('name'));$locale=get_locale();echo '<meta property="og:type" content="article">'."\n";echo '<meta property="og:site_name" content="'.esc_attr($site).'">'."\n";echo '<meta property="og:locale" content="'.esc_attr($locale).'">'."\n";echo '<meta property="og:title" content="'.esc_attr($title).'">'."\n";echo '<meta property="og:description" content="'.esc_attr($description).'">'."\n";echo '<meta property="og:url" content="'.esc_url($url).'">'."\n";if($image)echo '<meta property="og:image" content="'.esc_url($image).'">'."\n";echo '<meta name="twitter:card" content="'.($image?'summary_large_image':'summary').'">'."\n";echo '<meta name="twitter:title" content="'.esc_attr($title).'">'."\n";if($description)echo '<meta name="twitter:description" content="'.esc_attr($description).'">'."\n";if($image)echo '<meta name="twitter:image" content="'.esc_url($image).'">'."\n";}add_action('wp_head','bsktv_og_meta',7);
